import type React from 'react'
import {useCallback, useEffect, useId, useMemo, useRef, useState, type JSX} from 'react'
import {Text, Heading, ProgressBar, Link} from '@primer/react'
import CircleOcticon from '@github-ui/circle-octicon'
import {XIcon, CheckCircleFillIcon, CircleIcon, LockIcon, TasklistIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {useClickAnalytics} from '@github-ui/use-analytics'

import Styles from './TodoList.module.css'

export interface TodoListItem {
  label: string
  isCompleted?: boolean
  isLocked?: boolean
  url?: string
  onToggle?: (index: number) => void
  onClick?: (url: string) => void
}

export interface TodoListProps {
  // Colour for the `ProgressBar` component. Expects a valid Primer colour.
  color?: string
  // Colour for the circular progress indicator. Accepts any colour.
  progressColor?: string
  title: string
  items: TodoListItem[]
  // Current URL/path for analytics
  currentUrl?: string
  // Business/Enterprise ID for analytics
  businessId?: string
  //User ID for analytics
  userId?: string
  // Optional section under the items. The `completed` is shown once all items' `isCompleted` values are truthy.
  // The `default` is shown when not all items are completed.
  // If you don't need this, you can remove it and clean up the associated logic/styles.
  // Optional section under the items. The `completed` is shown once all items' `isCompleted` values are truthy.
  bottomElement?: Record<
    'default' | 'completed',
    {
      // Uses templating to inject the links. Any `{link}` in `label` will be replaced by an item in the `links` array, in order.
      // eg. `Please click on {link} then navigate to {link}` will inject items at index 0 and 1 in the `links` array.
      label: string
      link?: {
        label: string
        href: string
      }
    }
  >
  // Adjusts the positioning. The margins' value can be tweaked in the CSS file.
  // If this feature is no longer needed, feel free to delete this prop and cleanup its associated logic/styles.
  isFloating?: boolean
  // a11y ARIA labels. Currently both are applied to an item's icon.
  aria: {
    completedItem: string
    lockedItem: string
  }
  // Whether to flash the expanded state on mount
  hasIntro?: boolean
  // Callback triggered once the intro completes
  onIntroComplete?: () => void
  progressLabel?: string
  completionLabel?: string
}

const defaultProps: Partial<TodoListProps> = {
  color: 'done.emphasis',
  progressColor: 'var(--bgColor-done-emphasis)',
  isFloating: true,
  hasIntro: true,
  progressLabel: '{current}/{total} completed',
  completionLabel: 'All tasks completed!',
}

const PROGRESS_CIRCLE_RADIUS = 48 // px
const PROGRESS_CIRCLE_STROKE = 4 // px
const CIRCLE_BORDER_COLOR = 'var(--borderColor-muted)'

const TodoList: React.FC<TodoListProps> = props => {
  const initializedProps = {...defaultProps, ...props}
  const {
    color,
    progressColor,
    title,
    items,
    currentUrl,
    businessId,
    userId,
    bottomElement,
    aria,
    isFloating,
    hasIntro,
    onIntroComplete,
    progressLabel,
    completionLabel,
  } = initializedProps

  const [isOpen, setIsOpen] = useState<boolean>(false)
  const [isPlayingIntro, setIsPlayingIntro] = useState<boolean>(false)
  const [isProgressAnimating, setIsProgressAnimating] = useState<boolean>(false)
  const [isIntroDone, setIsIntroDone] = useState<boolean>(false)
  const introTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const progressTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const toggleRef = useRef<HTMLButtonElement>(null)

  const headingId = useId()
  const itemLabelId = useId()

  const progress = useMemo(
    () => parseFloat((items.filter(item => item.isCompleted).length / items.length).toFixed(2)) * 100,
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
    [items],
  )

  const completedItemsLabel = useMemo(
    () =>
      items.map(item => item.isCompleted).every(Boolean)
        ? completionLabel
        : progressLabel
            ?.replace('{current}', items.filter(item => item.isCompleted).length.toString())
            .replace('{total}', items.length.toString()),
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
    [completionLabel, items, progressLabel],
  )

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  useEffect(() => {
    const proceed = async () => {
      if (progressTimeoutRef.current) {
        clearTimeout(progressTimeoutRef.current)
        setIsProgressAnimating(false)
      }

      setIsProgressAnimating(true)

      progressTimeoutRef.current = await new Promise(resolve => setTimeout(resolve, 1000))
      progressTimeoutRef.current = null

      setIsProgressAnimating(false)
    }

    if (progress) proceed()
  }, [progress])

  useEffect(() => {
    const proceed = async () => {
      if (hasIntro) {
        if (introTimeoutRef.current) clearTimeout(introTimeoutRef.current)

        introTimeoutRef.current = await new Promise(resolve => setTimeout(resolve, 500))
        introTimeoutRef.current = null

        setIsPlayingIntro(true)

        introTimeoutRef.current = await new Promise(resolve => setTimeout(resolve, 2000))
        introTimeoutRef.current = null

        setIsPlayingIntro(false)
      }

      setIsIntroDone(true)
      if (onIntroComplete) {
        onIntroComplete()
      }
    }

    proceed()

    return () => {
      if (introTimeoutRef.current) clearTimeout(introTimeoutRef.current)
      if (progressTimeoutRef.current) clearTimeout(progressTimeoutRef.current)
    }
  }, [hasIntro, onIntroComplete])

  const toggleDOM = useMemo(
    () => (
      <button
        ref={toggleRef}
        className={clsx(Styles['TodoList__toggle'], isPlayingIntro && Styles['TodoList__toggle--isHighlighted'])}
        onClick={() => {
          setIsOpen(!isOpen)
        }}
        aria-haspopup="dialog"
        aria-expanded={isOpen ? 'true' : 'false'}
        aria-describedby={headingId}
        style={{'--size': `${PROGRESS_CIRCLE_RADIUS}px`} as React.CSSProperties}
      >
        {isOpen ? <XIcon data-testid="closeButton" size={16} /> : <TasklistIcon data-testid="openButton" size={16} />}
        <div className={Styles['TodoList__toggleLabel']}>
          <div className={Styles['TodoList__toggleLabelContent']}>
            <div className={Styles['TodoList__toggleLabelText']}>{title}</div>
            <div className={clsx({[Styles['TodoList__toggleLabelText']]: Styles.mutedText})}>{completedItemsLabel}</div>
          </div>
        </div>

        <div
          className={clsx(
            Styles['TodoList__toggleProgress'],
            !isIntroDone && Styles['TodoList__toggleProgress--isHidden'],
          )}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox={`0 0 ${2 * PROGRESS_CIRCLE_RADIUS} ${2 * PROGRESS_CIRCLE_RADIUS}`}
            aria-hidden="true"
            data-testid="progress-circle"
          >
            <circle
              cx={PROGRESS_CIRCLE_RADIUS}
              cy={PROGRESS_CIRCLE_RADIUS}
              r={PROGRESS_CIRCLE_RADIUS - PROGRESS_CIRCLE_STROKE / 2}
              stroke={CIRCLE_BORDER_COLOR}
              strokeWidth={PROGRESS_CIRCLE_STROKE}
              transform={`rotate(-90 ${PROGRESS_CIRCLE_RADIUS} ${PROGRESS_CIRCLE_RADIUS})`}
            />
            <circle
              cx={PROGRESS_CIRCLE_RADIUS}
              cy={PROGRESS_CIRCLE_RADIUS}
              r={PROGRESS_CIRCLE_RADIUS - PROGRESS_CIRCLE_STROKE / 2}
              stroke={progressColor}
              strokeWidth={PROGRESS_CIRCLE_STROKE}
              strokeDasharray={2 * Math.PI * PROGRESS_CIRCLE_RADIUS}
              strokeDashoffset={2 * Math.PI * PROGRESS_CIRCLE_RADIUS * (1 - progress / 100)}
              transform={`rotate(-90 ${PROGRESS_CIRCLE_RADIUS} ${PROGRESS_CIRCLE_RADIUS})`}
            />
          </svg>
        </div>
      </button>
    ),
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
    [isPlayingIntro, isOpen, headingId, title, completedItemsLabel, isIntroDone, progressColor, progress],
  )

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const renderBottomElement = useCallback(() => {
    if (!bottomElement) return null

    const isCompleted = items.map(item => item.isCompleted).every(Boolean)
    const config = isCompleted ? bottomElement.completed : bottomElement.default

    // Create the result by replacing each {link} placeholder with its corresponding Link component

    if (config.link) {
      const beforeLink = config.label.split('{link}')[0]
      const afterLink = config.label.split('{link}')[1] || ''

      return (
        <span className={Styles.mutedText}>
          {beforeLink}
          <Link href={config.link.href}>{config.link.label}</Link>
          {afterLink}
        </span>
      )
    }

    // No link, just show the label without {link} placeholders
    return <span className={Styles.mutedText}>{config.label.replace(/{link}/g, '')}</span>
    // eslint-disable-next-line react-hooks/preserve-manual-memoization
  }, [items, bottomElement])

  const contentDOM = useMemo(
    () => (
      <div className={clsx(Styles['TodoList__content'])} role="dialog" aria-modal="true" aria-label={title}>
        <div className={Styles['TodoList__contentHeadingBlock']}>
          <Heading id={headingId} as="h2" className={Styles['TodoList__contentHeading']}>
            {title}
          </Heading>
        </div>
        <div className={Styles['TodoList__contentProgress']}>
          <ProgressBar
            progress={progress}
            aria-label="Item progress"
            bg={color}
            animated={isProgressAnimating}
            barSize="small"
          />
          <span className={Styles.mutedText}>{completedItemsLabel}</span>
        </div>

        <div
          className={Styles['TodoList__contentItems']}
          {...(!isOpen ? ({inert: 'true'} as JSX.IntrinsicElements['div']) : {})}
        >
          {items.map((item, index) => {
            const CheckTag = item.onToggle && !item.isLocked ? 'button' : 'div'
            const LabelComponent = item.url ? Link : (Text as React.ComponentType<unknown>)

            return (
              <div
                key={`item_${index}`}
                data-testid={`todo-item-${item.label
                  .toLowerCase()
                  .replace(/\s+/g, '-')
                  .replace(/[^a-z0-9-]/g, '')}`}
                className={clsx(
                  Styles['TodoList__contentItem'],
                  item.isCompleted && Styles['TodoList__contentItem--isCompleted'],
                  item.isLocked && Styles['TodoList__contentItem--isLocked'],
                )}
              >
                <CheckTag
                  className={clsx(Styles['TodoList__contentItemCheck'])}
                  {...(CheckTag === 'button' && {
                    onClick: () => item.onToggle?.(index),
                    'aria-labelledby': `${itemLabelId}_${index}`,
                  })}
                >
                  {item.isLocked && (
                    <LockIcon
                      size={16}
                      aria-label={aria.lockedItem}
                      className={Styles['TodoList__contentItemCheckIcon']}
                    />
                  )}
                  {!item.isLocked && <CircleIcon size={16} />}
                  {!item.isLocked && (
                    <CircleOcticon
                      icon={CheckCircleFillIcon}
                      size={16}
                      className={clsx(Styles['TodoList__contentItemCheckIcon'])}
                      style={{backgroundColor: color}}
                      aria-label={aria.completedItem}
                    />
                  )}
                </CheckTag>
                <LabelComponent
                  id={`${itemLabelId}_${index}`}
                  className={Styles['TodoList__contentItemLabel']}
                  {...(item.url &&
                    !item.isLocked && {
                      href: item.url,
                      onClick: () => {
                        const location = currentUrl || 'unknown'
                        const enterpriseId = businessId || 'unknown'
                        const userIdValue = userId || 'unknown'

                        sendClickAnalyticsEvent({
                          category: 'enterprise_trial_account',
                          action: 'getting_started_trial',
                          label: `enterprise_id:${enterpriseId};user_id:${userIdValue};location:${location};content:${item.label}`,
                        })
                      },
                    })}
                >
                  {item.label}
                </LabelComponent>
              </div>
            )
          })}
        </div>

        {bottomElement && <div className={Styles['TodoList__contentBottom']}>{renderBottomElement()}</div>}
      </div>
    ),
    [
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      title,
      headingId,
      progress,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      color,
      isProgressAnimating,
      completedItemsLabel,
      isOpen,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      items,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      bottomElement,
      renderBottomElement,
      itemLabelId,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      aria.lockedItem,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      aria.completedItem,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      currentUrl,
      sendClickAnalyticsEvent,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      businessId,
      // eslint-disable-next-line react-hooks/preserve-manual-memoization
      userId,
    ],
  )

  return (
    <div
      className={clsx(
        Styles['TodoList'],
        isOpen && Styles['TodoList--isOpen'],
        isFloating && Styles['TodoList--isFloating'],
      )}
    >
      {toggleDOM}
      {contentDOM}
    </div>
  )
}

export {TodoList}
export default TodoList

try{ CIRCLE_BORDER_COLOR.displayName ||= 'CIRCLE_BORDER_COLOR' } catch {}
try{ LabelComponent.displayName ||= 'LabelComponent' } catch {}